CREATE TABLE raw_customers (
    row_id      integer PRIMARY KEY,
    full_name   text,
    email       text,
    phone       text,
    signup_date text,
    country     text,
    city        text
);

CREATE TABLE raw_orders (
    row_id         integer PRIMARY KEY,
    order_ref      text,
    customer_email text,
    order_date     text,
    amount         text,
    currency       text,
    status         text
);

CREATE TABLE survey_responses (
    response_id     integer PRIMARY KEY,
    respondent      text,
    q1_satisfaction text,
    q2_recommend    text,
    q3_comment      text,
    submitted       text
);

CREATE TABLE product_sales_wide (
    product text PRIMARY KEY,
    jan     numeric,
    feb     numeric,
    mar     numeric,
    apr     numeric,
    may     numeric,
    jun     numeric
);

CREATE TABLE monthly_sales_long (
    product text NOT NULL,
    month   text NOT NULL,
    revenue numeric(10,2),
    PRIMARY KEY (product, month)
);






